{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "description": "Measurement report provided by a CBSD.",
    "type": "object",
    "additionalproperties": true,
    "properties": {
        "eutraCarrierRssiRpt": {
            "type": "array",
            "description": "Report structured used by a CBSD when a measurement report type is EutraCarrierRssiNonTx or EutraCarrierRssiAlways",
            "items": {
                "$ref": "#/eutraCarrierRssiRptObject"
            }
        }
    },
    "eutraCarrierRssiRptObject": {
        "type": "object",
        "description": "Report for a particular Carrier RSSI measurement.",
        "required": [
            "measFrequency",
            "measBandwidth",
            "measCarrierRssi"
        ],
        "properties": {
            "measFrequency": {
                "type": "number",
                "description": "Frequency of the low end of the measured channel in Hz.",
                "minimum": 0
            },
            "measBandwidth": {
                "type": "number",
                "description": "Measurement bandwidth of the channel in Hz.",
                "minimum": 0
            },
            "measCarrierRssi": {
                "type": "number",
                "description": "Carrier RSSI measurement of the channel in dBm as per 3GPP TS 32.592.",
                "minimum": -100,
                "maximum": -25
            }
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "description": "Response data for SAS communications",
    "type": "object",
    "required": [
        "responseCode"
    ],
    "properties": {
        "responseCode": {
            "enum": [
                0,
                100,
                101,
                102,
                103,
                104,
                105,
                200,
                201,
                202,
                300,
                400,
                401,
                500,
                501,
                502
            ],
            "description": "An integer indicating the type of the response. 0 means success (no error)"
        },
        "responseMessage": {
            "type": "string",
            "description": "A detailed human-readable string describing the response."
        },
        "responseData": {
            "description": "Additional response-dependent structured data containing more information about an error.",
            "additionalProperties": true
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "description": "Fibaro Home Center Section JSON Schema",
    "name": "section",
    "type": "object",
    "properties": {
        "id": {
            "description": "Identifier for the section",
            "type": "integer",
            "minimum": 0
        },
        "name": {
            "description": "Name for the section",
            "type": "string",
            "maxLength": 20
        },
        "created": {
            "description": "Section creation timestamp",
            "type": "integer",
            "minimum": 0
        },
        "modified": {
            "description": "Section modification timestamp",
            "type": "integer",
            "minimum": 0
        },
        "sortOrder": {
            "description": "Sort order when displayed in GUI",
            "type": "integer",
            "minimum": 0
        }
    },
    "required": [
        "name"
    ],
    "additionalProperties": false
}

{
