{
    "title": "JSON schema for Web Application manifest files (schema extensions)",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "properties": {
        "mjs_access_whitelist": {
            "description": "The mjs_access_whitelist member is an array of rules that indicates the type of access the URLs matching the rule should have.",
            "type": "array",
            "items": {
                "$ref": "#/definitions/mjs_access_whitelist_rule"
            }
        }
    },
    "definitions": {
        "mjs_access_whitelist_rule": {
            "type": "object",
            "properties": {
                "url": {
                    "description": "A string that represents the URL pattern for which the rule should be applied to.",
                    "type": "string",
                    "format": "uri"
                },
                "apiAccess": {
                    "description": "A string that defines the type of access to the runtime API where the application is running.",
                    "enum": [
                        "none",
                        "all",
                        "AllowForWebOnly"
                    ]
                }
            }
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-07/schema",
    "title": "App Shell Target",
    "description": "App Shell target options for Build Facade.",
    "type": "object",
    "properties": {
        "browserTarget": {
            "type": "string",
            "description": "Target to build.",
            "pattern": "^[^:\\s]+:[^:\\s]+(:[^\\s]+)?$"
        },
        "serverTarget": {
            "type": "string",
            "description": "Server target to use for rendering the app shell.",
            "pattern": "^[^:\\s]+:[^:\\s]+(:[^\\s]+)?$"
        },
        "appModuleBundle": {
            "type": "string",
            "description": "Script that exports the Server AppModule to render. This should be the main JavaScript outputted by the server target. By default we will resolve the outputPath of the serverTarget and find a bundle named 'main' in it (whether or not there's a hash tag)."
        },
        "route": {
            "type": "string",
            "description": "The route to render.",
            "default": "/"
        },
        "inputIndexPath": {
            "type": "string",
            "description": "The input path for the index.html file. By default uses the output index.html of the browser target."
        },
        "outputIndexPath": {
            "type": "string",
            "description": "The output path of the index.html file. By default will overwrite the input file."
        }
    },
    "additionalProperties": false,
    "required": [
        "browserTarget",
        "serverTarget"
    ]
}

